<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import RunCenter from './RunCenter.vue'
import PlanManager from './PlanManager.vue'
import ScriptCard from './ScriptCard.vue'
import type { Config, MaaEndAdapter, MAAAdapter, Plan, PlanItem, Preset, Queue, RunItem, Runtime, Task } from './types'
import { useRunnerConnection } from './useRunnerConnection'

type HistoryRun = { id: string; queue_name: string; run_mode?: string; trigger_source: string; state: string; started_at: string; items: RunItem[]; scheduler_skips?: string[] }
type DeferredPreset = { presetId: string; path: string }
type Page = 'scripts' | 'editor' | 'schedule' | 'history' | 'settings'
type ScriptExecution = { kind: 'idle' | 'queued' | 'running' | 'waiting_manual' | 'closing' | 'cooling_down' | 'succeeded' | 'failed' | 'stopped'; label: string; detail?: string }

const config = ref<Config>({ schema_version: 3, queues: [], tasks: [], plans: [], fired_slots: [], startup_fired_dates: {} })
const runtime = ref<Runtime>({ busy: false, activeTaskId: null, cooldownSeconds: 0, cooldownUntil: null, runCenter: null, run: null })
const presets = ref<Preset[]>([]); const history = ref<HistoryRun[]>([]); const logs = ref<string[]>([])
const page = ref<Page>('scripts'); const query = ref(''); const notice = ref('正在确认本地后端…'); const migrationNotice = ref('')
const editingScriptId = ref<string | null>(null); const selectedPlanId = ref<string | null>(null); const selectedHistoryRunId = ref<string | null>(null)
const expandedHistory = ref(new Set<string>()); const draggedScript = ref<string | null>(null); const draggedPlanScriptId = ref<string | null>(null); const allRunProblems = ref<string[]>([])
const selectionIssues = ref<Record<string, string>>({}); const deferredPresets = ref<Record<string, DeferredPreset>>({}); const presetRequestSerial = new Map<string, number>()
const confirmationPending = ref(false); const countdownNow = ref(Date.now()); const saveState = ref<'saved' | 'saving' | 'draft' | 'failed'>('saved')
const appVersion = ref('开发版本读取中'); const backendDetail = ref(''); let localRevision = 0; let savedRevision = 0; let saveFlight: Promise<void> | undefined; let historyFlight: Promise<void> | undefined; let terminalHistoryId: string | null = null; let countdownTimer: number | undefined; let exitAppRunId: string | null = null
const taskBook = computed(() => new Map(config.value.tasks.map((task) => [task.id, task])))
const editingScript = computed(() => config.value.queues.find((item) => item.id === editingScriptId.value) || null)
const editingTask = computed(() => editingScript.value ? scriptTask(editingScript.value) : null)
const selectedPlan = computed(() => config.value.plans.find((item) => item.id === selectedPlanId.value) || null)
const hours = Array.from({ length: 24 }, (_, index) => String(index).padStart(2, '0'))
const minutes = Array.from({ length: 60 }, (_, index) => String(index).padStart(2, '0'))
const visibleScripts = computed(() => { const text = query.value.trim().toLocaleLowerCase(); return !text ? config.value.queues : config.value.queues.filter((script) => `${script.name} ${scriptTask(script)?.name || ''} ${presetSummary(script)}`.toLocaleLowerCase().includes(text)) })
const hasUnsavedDraft = computed(() => localRevision > savedRevision)
const isMaa = computed(() => editingTask.value?.preset_id === 'maa'); const isMaaEnd = computed(() => editingTask.value?.preset_id === 'maaend')
const editorSaveLabel = computed(() => runtime.value.busy ? '本轮运行中，配置已锁定' : saveState.value === 'saving' ? '保存中…' : saveState.value === 'failed' ? '保存失败，请重试' : hasUnsavedDraft.value ? '未保存草稿' : '已保存')
const cooldown = computed(() => { const until = runtime.value.cooldownUntil; if (!until) return runtime.value.cooldownSeconds || 0; countdownNow.value; return Math.max(0, Math.ceil((new Date(until).getTime() - Date.now()) / 1000)) })
const connection = useRunnerConnection(refresh, handleRealtime)
const connectionSummary = computed(() => connection.restOnline.value ? (connection.realtimeState.value === 'online' ? '本地后端与实时状态已连接' : '实时状态正在恢复') : '本地后端不可用')
const diagnosticText = computed(() => JSON.stringify({ API: connection.restOnline.value ? '在线' : '离线', 实时状态: connection.realtimeLabel.value, 主进程: backendDetail.value || '无' }, null, 2))

function uid() { return crypto.randomUUID() }
function normalizeConfig(raw: Config) { raw.plans.forEach((plan) => { plan.script_ids = plan.items.map((item) => item.script_id); plan.run_on_startup = plan.startup_mode !== 'never' }); return raw }
function directoryOf(path: string) { return path.replace(/[\\/][^\\/]+$/, '') }
function fileName(path: string) { return path.replace(/^.*[\\/]/, '').toLocaleLowerCase() }
function day(value: number) { return ['一', '二', '三', '四', '五', '六', '日'][value] }
function scriptTasks(script: Queue) { return script.task_ids.map((id) => taskBook.value.get(id)).filter(Boolean) as Task[] }
function scriptTask(script: Queue) { return scriptTasks(script)[0] || null }
function draft(): Task { return { id: uid(), name: '新程序', executable: '', arguments: [], working_directory: null, allow_manual_confirmation: true, allow_process_exit: true, log_path: null, success_log: null, success_log_mode: 'keyword', failure_log: null, failure_log_mode: 'keyword', success_log_rules: [], failure_log_rules: [], preset_id: null, preset_evidence: null, timeout_seconds: 600, maa_adapter: null, maaend_adapter: null } }
function presetFor(task: Task) { return presets.value.find((preset) => preset.id === task.preset_id) }
function presetLabel(task: Task | null) { return task ? (presetFor(task)?.label || '通用程序') : '通用程序' }
function presetSummary(script: Queue) { return presetLabel(scriptTask(script)) }
function matchesPreset(task: Task, executable = task.executable) { const preset = presetFor(task); return !task.preset_id || !!preset?.executables.some((name) => name.toLocaleLowerCase() === fileName(executable)) }
function presetRuleText(task: Task, type: 'success' | 'failure') { const storedRules = type === 'success' ? task.success_log_rules : task.failure_log_rules; const presetRules = type === 'success' ? presetFor(task)?.successRules : presetFor(task)?.failureRules; const rules = storedRules.length ? storedRules : (presetRules || []); return rules.map((rule) => `${rule.mode === 'regex' ? '正则' : '关键字'}：${rule.pattern}`).join('；') || '无（由人工确认完成）' }
function report(title: string, error: unknown) { notice.value = `${title}：${error instanceof Error ? error.message : String(error)}` }
function taskProblem(task: Task): string | null { if (!task.executable.trim()) return '未选择程序路径'; if (task.preset_id && !matchesPreset(task)) return '预设路径不匹配'; if (task.preset_id && !task.preset_evidence) return '预设规则尚未应用'; return null }
function scriptProblems(script: Queue) { const task = scriptTask(script); return !task ? [`软件脚本“${script.name}”缺少程序`] : taskProblem(task) ? [`软件脚本“${script.name}”：${taskProblem(task)}`] : [] }
function scriptBlocked(script: Queue) { return scriptProblems(script).length > 0 }
function itemReason(item: RunItem) { return item.error_summary || (item.exit_code !== null && item.exit_code !== undefined ? `退出码 ${item.exit_code}` : item.completion_source || '未提供摘要') }
function itemOutcome(item: RunItem) { return item.state === 'failed' ? `失败：${itemReason(item)}` : item.state === 'succeeded' ? `成功：${item.completion_source || '已完成'}` : item.state }
function runHasFailures(run: Pick<HistoryRun, 'items'>) { return run.items.some((item) => item.state === 'failed') }
function executionFor(script: Queue): ScriptExecution { const item = runtime.value.run?.items.find((candidate) => candidate.script_id === script.id || candidate.task_id === scriptTask(script)?.id); if (!item) return { kind: 'idle', label: '' }; if (item.state === 'queued') return { kind: 'queued', label: '等待运行' }; if (['validating', 'starting', 'monitoring'].includes(item.state)) return { kind: 'running', label: '运行中' }; if (item.state === 'waiting_manual') return { kind: 'waiting_manual', label: '等待确认' }; if (['closing', 'force_closing'].includes(item.state)) return { kind: 'closing', label: '正在收尾' }; if (item.state === 'cooling_down') return { kind: 'cooling_down', label: '冷却中' }; if (item.state === 'succeeded') return { kind: 'succeeded', label: '已完成', detail: item.completion_source || undefined }; if (item.state === 'failed') return { kind: 'failed', label: '失败', detail: itemReason(item) }; return { kind: 'stopped', label: '已停止' } }

async function refreshHistory(focus?: string) { if (!connection.restOnline.value || historyFlight) return historyFlight; historyFlight = (async () => { const data = await connection.request('/api/history') as { runs: HistoryRun[] }; history.value = data.runs; if (focus) { selectedHistoryRunId.value = focus; expandedHistory.value = new Set([...expandedHistory.value, focus]) } })().catch((error) => report('无法刷新运行历史', error)).finally(() => { historyFlight = undefined }); return historyFlight }
async function refresh() { const remote = normalizeConfig(await connection.request('/api/config') as Config); remote.plans ||= []; if (!hasUnsavedDraft.value) config.value = remote; selectedPlanId.value ??= config.value.plans[0]?.id || null; runtime.value = await connection.request('/api/runtime') as Runtime; migrationNotice.value = runtime.value.migrationNotice || ''; presets.value = await connection.request('/api/presets') as Preset[]; await refreshHistory(); await reconcileLoadedPresets(); if (hasUnsavedDraft.value) await flushSave(); if (migrationNotice.value) notice.value = migrationNotice.value }
function handleRealtime(event: { type: string; data: unknown }) { if (event.type === 'runtime') { runtime.value = event.data as Runtime; const completion = runtime.value.completionAction; if (completion?.action === 'exit_app' && completion.status === 'executing' && exitAppRunId !== completion.runId) { exitAppRunId = completion.runId; void window.desktopRunner?.quitApp?.() } if (confirmationPending.value && runtime.value.runCenter?.currentState !== 'waiting_manual') confirmationPending.value = false; const finished = runtime.value.run && ['completed', 'stopped'].includes(runtime.value.run.state); if (finished && runtime.value.run!.id !== terminalHistoryId) { terminalHistoryId = runtime.value.run!.id; void refreshHistory(runtime.value.run!.id); notice.value = runtime.value.run!.state === 'stopped' ? '本轮已停止，不会启动下一项。' : runtime.value.run!.items.some((item) => item.state === 'failed') ? '整轮执行完成，存在失败项。' : '整轮执行完成。' } } if (event.type === 'config' && !hasUnsavedDraft.value) config.value = normalizeConfig(event.data as Config); if (event.type === 'schedule') notice.value = (event.data as { message: string }).message; if (event.type === 'log') logs.value = [...logs.value.slice(-39), (event.data as { message: string }).message] }
async function flushSave() { if (saveFlight) return saveFlight; saveFlight = (async () => { if (savedRevision < localRevision) saveState.value = 'saving'; while (connection.restOnline.value && savedRevision < localRevision) { const revision = localRevision; const snapshot = JSON.parse(JSON.stringify(config.value)) as Config; try { const accepted = await connection.request('/api/config', { method: 'PUT', headers: { 'content-type': 'application/json' }, body: JSON.stringify(snapshot) }) as Config; accepted.plans ||= []; savedRevision = revision; if (revision === localRevision) config.value = normalizeConfig(accepted) } catch (error) { saveState.value = 'failed'; report('保存失败，草稿将保留', error); break } } if (savedRevision === localRevision && connection.restOnline.value) saveState.value = 'saved' })().finally(() => { saveFlight = undefined }); return saveFlight }
function save() { localRevision += 1; if (!connection.restOnline.value) { saveState.value = 'draft'; return Promise.resolve() } return flushSave() }
async function saveEditorChanges() { await save(); if (savedRevision === localRevision) notice.value = '保存更改已完成。' }
function openEditor(script: Queue) { editingScriptId.value = script.id; page.value = 'editor' }
function closeEditor() { editingScriptId.value = null; page.value = 'scripts' }
function newScript() { const task = draft(); const script: Queue = { id: uid(), name: task.name, task_ids: [task.id], time_slots: [] }; config.value.tasks.push(task); config.value.queues.push(script); void save(); openEditor(script) }
function duplicateScript(script: Queue) { const task = scriptTask(script); if (!task) return; const cloned = structuredClone(task); cloned.id = uid(); cloned.name += ' 副本'; const clone: Queue = { id: uid(), name: cloned.name, task_ids: [cloned.id], time_slots: [] }; config.value.tasks.push(cloned); config.value.queues.push(clone); void save() }
function deleteScript(script: Queue) { if (runtime.value.busy) return; const ids = new Set(script.task_ids); config.value.queues = config.value.queues.filter((item) => item.id !== script.id); config.value.tasks = config.value.tasks.filter((task) => !ids.has(task.id)); config.value.plans = config.value.plans.map((plan) => ({ ...plan, items: plan.items.filter((item) => item.script_id !== script.id) })); if (editingScriptId.value === script.id) closeEditor(); void save() }
function moveScript(targetId: string) { if (!draggedScript.value || draggedScript.value === targetId) return; const from = config.value.queues.findIndex((script) => script.id === draggedScript.value); const to = config.value.queues.findIndex((script) => script.id === targetId); if (from < 0 || to < 0) return; const [moved] = config.value.queues.splice(from, 1); config.value.queues.splice(to, 0, moved); void save() }
function moveScriptBy(script: Queue, direction: -1 | 1) { const from = config.value.queues.findIndex((item) => item.id === script.id); const to = from + direction; if (to < 0 || to >= config.value.queues.length) return; [config.value.queues[from], config.value.queues[to]] = [config.value.queues[to], config.value.queues[from]]; void save() }
function clearAppliedRules(task: Task) { task.preset_evidence = null; task.log_path = null; task.success_log_rules = []; task.failure_log_rules = []; task.allow_manual_confirmation = true; task.allow_process_exit = false }
async function applyPreset(task: Task, path: string, serial: number) { const presetId = task.preset_id; if (!presetId) return; const oldMaaEnd = task.maaend_adapter ? { game_executable: task.maaend_adapter.game_executable, game_arguments: [...task.maaend_adapter.game_arguments], game_wait_seconds: task.maaend_adapter.game_wait_seconds, close_game_on_finish: task.maaend_adapter.close_game_on_finish } : null; const applied = await connection.request(`/api/presets/${presetId}/apply`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ executable: path, task_id: task.id, name: task.name === '新程序' ? '' : task.name }) }) as Task; if (presetRequestSerial.get(task.id) !== serial || task.executable !== path) return; Object.assign(task, applied); if (presetId === 'maaend' && oldMaaEnd && task.maaend_adapter) Object.assign(task.maaend_adapter, oldMaaEnd, { installation_directory: directoryOf(path) }); const script = config.value.queues.find((item) => item.task_ids[0] === task.id); if (script && script.name === '新程序') script.name = task.name; delete selectionIssues.value[task.id]; await save() }
async function synchronizeExecutable(task: Task, raw: string) { const path = raw.trim(); const serial = (presetRequestSerial.get(task.id) || 0) + 1; presetRequestSerial.set(task.id, serial); task.executable = path; task.working_directory = path ? directoryOf(path) : null; if (!task.preset_id || !path) return save(); clearAppliedRules(task); if (!matchesPreset(task, path)) { selectionIssues.value = { ...selectionIssues.value, [task.id]: `已保留路径，但该 EXE 不符合 ${presetLabel(task)} 模板。请重新选择或切换通用程序。` }; return save() } try { await applyPreset(task, path, serial) } catch (error) { selectionIssues.value = { ...selectionIssues.value, [task.id]: '预设规则未能应用；路径已保留。' }; await save(); report('无法应用预设规则', error) } }
function selectPreset(task: Task) { if (!task.preset_id) { task.preset_evidence = null; task.maa_adapter = null; task.maaend_adapter = null; void save(); return } const preset = presetFor(task); if (task.name === '新程序' && preset) { task.name = preset.label; const script = config.value.queues.find((item) => item.task_ids[0] === task.id); if (script && script.name === '新程序') script.name = preset.label } if (task.preset_id === 'maa') task.maa_adapter ||= { installation_directory: task.executable ? directoryOf(task.executable) : null, adb_executable: null, adb_address: null, last_check_at: null, last_check_ok: null, last_check_message: null }; if (task.preset_id === 'maaend') task.maaend_adapter ||= { installation_directory: task.executable ? directoryOf(task.executable) : null, game_executable: null, game_arguments: [], game_wait_seconds: 60, close_game_on_finish: true }; if (task.executable) void synchronizeExecutable(task, task.executable); else void save() }
async function reconcileLoadedPresets() { if (runtime.value.busy || !connection.restOnline.value || hasUnsavedDraft.value) return; for (const task of config.value.tasks) { if (task.preset_id && task.executable && (!task.preset_evidence || (presetFor(task)?.requiresLogRules && (!task.success_log_rules.length || !task.failure_log_rules.length)))) await synchronizeExecutable(task, task.executable) } }
async function choose(task: Task) { const result = await window.desktopRunner?.selectExecutable(task.preset_id); if (result?.path) await synchronizeExecutable(task, result.path) }
async function chooseInstallDirectory(task: Task, executable: 'MAA.exe' | 'MaaEnd.exe') { const result = await window.desktopRunner?.selectDirectory?.(); if (!result?.path) return; await synchronizeExecutable(task, `${result.path}\\${executable}`) }
function updateInstallDirectory(task: Task, executable: 'MAA.exe' | 'MaaEnd.exe', event: Event) { const directory = (event.target as HTMLInputElement).value.trim(); if (directory) void synchronizeExecutable(task, `${directory.replace(/[\\/]+$/, '')}\\${executable}`) }
async function chooseStandalone(target: 'adb' | 'game', task: Task) { const result = await window.desktopRunner?.selectExecutable(null); if (!result?.path) return; if (target === 'adb') ensureMaa(task).adb_executable = result.path; else ensureMaaEnd(task).game_executable = result.path; void save() }
function ensureMaa(task: Task): MAAAdapter { return task.maa_adapter ||= { installation_directory: task.executable ? directoryOf(task.executable) : null, adb_executable: null, adb_address: null, last_check_at: null, last_check_ok: null, last_check_message: null } }
function ensureMaaEnd(task: Task): MaaEndAdapter { return task.maaend_adapter ||= { installation_directory: task.executable ? directoryOf(task.executable) : null, game_executable: null, game_arguments: [], game_wait_seconds: 60, close_game_on_finish: true } }
async function checkAdb(task: Task) { const adapter = ensureMaa(task); try { const result = await connection.request('/api/adb-check', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ executable: adapter.adb_executable, address: adapter.adb_address }) }) as { ok: boolean; message: string; checkedAt: string }; adapter.last_check_ok = result.ok; adapter.last_check_message = result.message; adapter.last_check_at = result.checkedAt; notice.value = result.ok ? '安卓模拟器连接检测通过。' : `连接检测未通过：${result.message}；运行时仍会继续启动 MAA GUI。`; void save() } catch (error) { report('连接检测无法完成', error) } }
function updateExecutable(task: Task, event: Event) { void synchronizeExecutable(task, (event.target as HTMLInputElement).value) }
function setText(task: Task, key: 'working_directory' | 'log_path' | 'success_log' | 'failure_log', event: Event) { const value = (event.target as HTMLInputElement).value.trim() || null; const automatic = key === 'success_log' ? task.success_log_rules : key === 'failure_log' ? task.failure_log_rules : []; if (value && automatic.some((rule) => rule.pattern === value)) { notice.value = '自定义规则不能与模板规则重复。'; return }; task[key] = value; void save() }
function setArgs(task: Task, event: Event, field: 'arguments' | 'game_arguments' = 'arguments') { const values = ((event.target as HTMLInputElement).value.trim().match(/(?:[^\s"]+|"[^"]*")+/g) || []).map((part) => part.replaceAll('"', '')); if (field === 'arguments') task.arguments = values; else ensureMaaEnd(task).game_arguments = values; void save() }
function useGenericProgram(task: Task) { task.preset_id = null; task.preset_evidence = null; task.maa_adapter = null; task.maaend_adapter = null; delete selectionIssues.value[task.id]; void save() }
async function runScript(script: Queue) { const problems = scriptProblems(script); if (problems.length) { notice.value = problems.join('；'); return } try { await connection.request('/api/start', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ queue_id: script.id }) }); notice.value = `已开始软件脚本“${script.name}”` } catch (error) { report('无法运行脚本', error) } }
async function runAllScripts() { allRunProblems.value = config.value.queues.flatMap(scriptProblems); if (allRunProblems.value.length) { notice.value = '全部脚本尚未完成配置。'; return } try { await connection.request('/api/start-all', { method: 'POST' }); notice.value = '已按软件脚本顺序开始运行。' } catch (error) { report('无法运行全部脚本', error) } }
async function stop() { try { await connection.request('/api/stop', { method: 'POST' }); notice.value = '已请求停止；不会派发下一项。' } catch (error) { report('停止请求未送达', error) } }
async function confirm(taskId: string) { if (confirmationPending.value) return; try { await connection.request('/api/confirm', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ task_id: taskId }) }); confirmationPending.value = true } catch (error) { report('人工确认未被接受', error) } }
function newPlan() { if (config.value.queues.length < 2) return; const plan: Plan = { id: uid(), name: '新计划', items: config.value.queues.slice(0, 2).map((script) => ({ id: uid(), script_id: script.id, days: [0, 1, 2, 3, 4, 5, 6] })), time_slots: [], startup_mode: 'never', scheduled_enabled: true, completion_action: 'none', completion_delay_minutes: 0, script_ids: [], run_on_startup: false }; config.value.plans.push(plan); selectedPlanId.value = plan.id; void save() }
function deletePlan(plan: Plan) { config.value.plans = config.value.plans.filter((item) => item.id !== plan.id); selectedPlanId.value = config.value.plans[0]?.id || null; void save() }
function planScript(item: PlanItem) { return config.value.queues.find((script) => script.id === item.script_id) || null }
function planScripts(plan: Plan) { return plan.items.map(planScript).filter(Boolean) as Queue[] }
function addPlanScript(plan: Plan, event: Event) { const id = (event.target as HTMLSelectElement).value; if (!id || plan.items.some((item) => item.script_id === id)) return; plan.items.push({ id: uid(), script_id: id, days: [0, 1, 2, 3, 4, 5, 6] }); (event.target as HTMLSelectElement).value = ''; void save() }
function movePlanScript(plan: Plan, index: number, direction: -1 | 1) { const target = index + direction; if (target < 0 || target >= plan.items.length) return; [plan.items[index], plan.items[target]] = [plan.items[target], plan.items[index]]; void save() }
function dropPlanScript(plan: Plan, targetId: string) { const sourceId = draggedPlanScriptId.value; if (!sourceId || sourceId === targetId) return; const from = plan.items.findIndex((item) => item.id === sourceId); const to = plan.items.findIndex((item) => item.id === targetId); if (from < 0 || to < 0) return; const [moved] = plan.items.splice(from, 1); plan.items.splice(to, 0, moved); draggedPlanScriptId.value = null; void save() }
function removePlanScript(plan: Plan, id: string) { plan.items = plan.items.filter((item) => item.id !== id); void save() }
function addPlanSlot(plan: Plan) { plan.time_slots.push({ id: uid(), enabled: true, days: [0, 1, 2, 3, 4, 5, 6], time: '09:00' }); void save() }
function removePlanSlot(plan: Plan, id: string) { plan.time_slots = plan.time_slots.filter((item) => item.id !== id); void save() }
function setSlotPart(slot: { time: string }, part: 'hour' | 'minute', value: string) { const [hour, minute] = slot.time.split(':'); slot.time = `${part === 'hour' ? value : hour}:${part === 'minute' ? value : minute}`; void save() }
function setStartupPlan(plan: Plan) { if (plan.startup_mode !== 'never') config.value.plans.forEach((item) => { if (item.id !== plan.id) item.startup_mode = 'never' }); void save() }
function planIssues(plan: Plan) { const issues: string[] = []; const ids = plan.items.map((item) => item.script_id); if (ids.length < 2) issues.push('至少需要两个软件脚本'); if (new Set(ids).size !== ids.length) issues.push('不能重复添加同一软件脚本'); if (ids.some((id) => !config.value.queues.some((script) => script.id === id))) issues.push('包含已删除的软件脚本'); if (plan.scheduled_enabled && !plan.time_slots.some((slot) => slot.enabled)) issues.push('未设置启用的定时'); if (plan.scheduled_enabled) for (const other of config.value.plans.filter((item) => item.id !== plan.id && item.scheduled_enabled)) for (const slot of plan.time_slots.filter((item) => item.enabled)) for (const candidate of other.time_slots.filter((item) => item.enabled)) if (slot.time === candidate.time && slot.days.some((value) => candidate.days.includes(value))) issues.push(`与计划“${other.name}”存在同刻冲突（${slot.time}）`); return [...new Set(issues)] }
function nextTrigger(plan: Plan) { const slot = plan.scheduled_enabled && plan.time_slots.find((item) => item.enabled); return slot ? `${slot.days.map((item) => '周' + day(item)).join('、')} ${slot.time}` : '未设置' }
async function cancelCompletionAction() { try { await connection.request('/api/cancel-completion-action', { method: 'POST' }); notice.value = '已取消完成后操作。' } catch (error) { report('无法取消完成后操作', error) } }
function openFailureDetails(runId: string) { selectedHistoryRunId.value = runId; expandedHistory.value = new Set([...expandedHistory.value, runId]); page.value = 'history' }
function toggleHistory(id: string) { const next = new Set(expandedHistory.value); next.has(id) ? next.delete(id) : next.add(id); expandedHistory.value = next }
async function refreshDiagnostics() { backendDetail.value = (await window.desktopRunner?.getBackendStatus?.())?.detail || '' }
onMounted(async () => { countdownTimer = window.setInterval(() => { countdownNow.value = Date.now() }, 250); appVersion.value = (await window.desktopRunner?.getBuildInfo?.())?.version || '开发版本不可用'; document.title = `顺序任务调度器 ${appVersion.value}`; await connection.connect(); await refreshDiagnostics(); notice.value = connection.restOnline.value ? '本地后端已就绪。' : '本地后端尚不可用；草稿会保留。' })
onBeforeUnmount(() => { if (countdownTimer) window.clearInterval(countdownTimer); connection.dispose() })
</script>

<template>
  <main class="app"><aside class="side"><div class="brand"><span>◆</span><b>顺序任务调度器 {{ appVersion }}</b><small>本地软件执行器</small></div><nav><button :class="{ active: page === 'scripts' || page === 'editor' }" @click="page = 'scripts'; editingScriptId = null">脚本</button><button :class="{ active: page === 'schedule' }" @click="page = 'schedule'">计划</button><button :class="{ active: page === 'history' }" @click="page = 'history'">历史</button><button :class="{ active: page === 'settings' }" @click="page = 'settings'">设置</button></nav><p>只操作本轮受管 PID，不扫描同名程序。</p></aside>
    <section class="content">
      <header v-if="page !== 'editor'"><div><h1>{{ page === 'scripts' ? '脚本管理' : page === 'schedule' ? '计划管理' : page === 'history' ? '运行历史' : '连接与设置' }}</h1><p>{{ connectionSummary }}</p></div><div class="actions"><span class="connection-chip" :class="{ offline: !connection.restOnline.value }">API {{ connection.restOnline.value ? '在线' : '离线' }}</span><span class="connection-chip" :class="{ warning: connection.realtimeState.value !== 'online' }">{{ connection.realtimeLabel.value }}</span><button class="danger" :disabled="!runtime.busy" @click="stop">全局停止</button></div></header>
      <RunCenter :runtime="runtime" :countdown="cooldown" :confirmation-pending="confirmationPending" @confirm="confirm" @show-failures="openFailureDetails" @cancel-completion-action="cancelCompletionAction" />
      <PlanManager v-if="page === 'schedule'" :config="config" :selected-plan-id="selectedPlanId" :busy="runtime.busy" @update:selected-plan-id="selectedPlanId = $event" @save="save" />
      <p v-if="migrationNotice" class="migration-notice" role="status">{{ migrationNotice }}</p><p class="notice"><span>{{ notice }}</span><span v-if="hasUnsavedDraft" class="draft-state">未保存草稿</span></p>
      <section v-if="page === 'scripts'" class="scripts-page"><div class="toolbar"><input v-model="query" placeholder="搜索软件脚本或预设"><div><button class="primary" :disabled="runtime.busy" @click="newScript">＋ 新建脚本</button><button class="run-all" :disabled="runtime.busy || !config.queues.length" @click="runAllScripts">▶ 运行全部脚本</button></div></div><div v-if="allRunProblems.length" class="run-problems"><b>无法运行全部脚本</b><ul><li v-for="problem in allRunProblems" :key="problem">{{ problem }}</li></ul></div><p v-if="!visibleScripts.length" class="empty">没有软件脚本。新建后直接配置一个软件。</p><ScriptCard v-for="script in visibleScripts" :key="script.id" :script="script" :task="scriptTask(script)" :locked="runtime.busy" :blocked="scriptBlocked(script)" :execution="executionFor(script)" :preset-summary="presetSummary(script)" @edit="openEditor(script)" @run="runScript(script)" @duplicate="duplicateScript(script)" @remove="deleteScript(script)" @dragstart="draggedScript = script.id" @drop="moveScript(script.id)" @move="moveScriptBy(script, $event)" /></section>
      <section v-else-if="page === 'editor' && editingScript && editingTask" class="editor-page"><div class="editor-navigation"><span class="editor-breadcrumb">脚本管理 / 编辑软件</span><div class="editor-navigation-actions"><button v-if="runtime.busy" class="danger" @click="stop">全局停止</button><button @click="closeEditor">← 返回</button></div></div><section class="editor-sheet specialized-editor"><div class="editor-sheet-title"><div><h2>{{ editingTask.name }} 脚本配置</h2><small>当前软件的启动、完成判断与安全编排。</small></div><div class="editor-sheet-actions"><b>{{ presetLabel(editingTask) }}</b><small :class="'save-' + saveState">{{ editorSaveLabel }}</small><button class="primary" :disabled="runtime.busy || saveState === 'saving'" @click="saveEditorChanges">{{ saveState === 'saving' ? '保存中…' : '保存更改' }}</button></div></div><aside class="editor-guidance"><b>使用说明</b><span>一个软件脚本只对应一个软件；运行期间配置锁定。预设规则只读，自定义规则与模板规则分开保存。</span></aside>
        <section class="editor-section"><div class="section-heading"><div><h3>基本信息</h3></div><small>名称会出现在脚本、计划、运行中心和历史记录中。</small></div><div class="basic-grid"><label class="script-name">软件脚本名称<input v-model="editingTask.name" aria-label="软件名称" :disabled="runtime.busy" @change="editingScript.name = editingTask.name; save()"></label><label v-if="isMaa" class="path">MAA 安装目录<div><input :value="editingTask.maa_adapter?.installation_directory || directoryOf(editingTask.executable)" placeholder="请选择含 MAA.exe 的目录" :disabled="runtime.busy" @change="updateInstallDirectory(editingTask, 'MAA.exe', $event)"><button :disabled="runtime.busy" @click="chooseInstallDirectory(editingTask, 'MAA.exe')">选择目录</button></div></label><label v-else-if="isMaaEnd" class="path">MaaEnd 安装目录<div><input :value="editingTask.maaend_adapter?.installation_directory || directoryOf(editingTask.executable)" placeholder="请选择含 MaaEnd.exe 的目录" :disabled="runtime.busy" @change="updateInstallDirectory(editingTask, 'MaaEnd.exe', $event)"><button :disabled="runtime.busy" @click="chooseInstallDirectory(editingTask, 'MaaEnd.exe')">选择目录</button></div></label><label v-else class="path">程序完整路径<div><input :value="editingTask.executable" placeholder="请选择 .exe" :disabled="runtime.busy" @change="updateExecutable(editingTask, $event)"><button :disabled="runtime.busy" @click="choose(editingTask)">选择软件</button></div></label></div><p v-if="selectionIssues[editingTask.id]" class="selection-warning">{{ selectionIssues[editingTask.id] }}<span><button @click="choose(editingTask)">重新选择</button><button @click="useGenericProgram(editingTask)">切换通用程序</button></span></p></section>
        <section class="editor-section editor-run-config"><div class="section-heading"><div><h3>运行配置</h3></div><small>仅显示本应用可实际启动与监测的字段。</small></div><div class="grid"><label>软件预设<select v-model="editingTask.preset_id" :disabled="runtime.busy" @change="selectPreset(editingTask)"><option :value="null">通用程序</option><option v-for="preset in presets" :key="preset.id" :value="preset.id">{{ preset.label }}</option></select></label><label>超时（秒）<input v-model.number="editingTask.timeout_seconds" type="number" min="1" :disabled="runtime.busy" @change="save"></label><label>启动参数<input :value="editingTask.arguments.join(' ')" :disabled="runtime.busy" @change="setArgs(editingTask, $event)"></label><label>工作目录<input :value="editingTask.working_directory || ''" :disabled="runtime.busy" @change="setText(editingTask, 'working_directory', $event)"></label><label>日志文件<input :value="editingTask.log_path || ''" :disabled="runtime.busy" @change="setText(editingTask, 'log_path', $event)"></label></div></section>
        <section v-if="isMaa" class="editor-section"><div class="section-heading"><div><h3>安卓模拟器连接</h3></div><small>只做 ADB 连通预检，不改写 MAA 或模拟器配置。</small></div><div class="grid"><label class="path">ADB 程序<div><input v-model="ensureMaa(editingTask).adb_executable" placeholder="adb.exe" :disabled="runtime.busy" @change="save"><button :disabled="runtime.busy" @click="chooseStandalone('adb', editingTask)">选择 ADB</button></div></label><label>连接地址<input v-model="ensureMaa(editingTask).adb_address" placeholder="例如 127.0.0.1:5555" :disabled="runtime.busy" @change="save"></label></div><div class="adapter-result" :class="{ good: ensureMaa(editingTask).last_check_ok, bad: ensureMaa(editingTask).last_check_ok === false }"><span>{{ ensureMaa(editingTask).last_check_message || '尚未检测安卓模拟器连接。' }}</span><small v-if="ensureMaa(editingTask).last_check_at">最近检测：{{ ensureMaa(editingTask).last_check_at }}</small><button :disabled="runtime.busy" @click="checkAdb(editingTask)">检测连接</button></div></section>
        <section v-if="isMaaEnd" class="editor-section"><div class="section-heading"><div><h3>Windows 游戏启动编排</h3></div><small>仅管理本轮由本应用创建的 Windows 游戏进程。</small></div><div class="grid"><label class="path">游戏 EXE<div><input v-model="ensureMaaEnd(editingTask).game_executable" placeholder="可留空：直接启动 MaaEnd" :disabled="runtime.busy" @change="save"><button :disabled="runtime.busy" @click="chooseStandalone('game', editingTask)">选择游戏</button></div></label><label>游戏启动参数<input :value="ensureMaaEnd(editingTask).game_arguments.join(' ')" :disabled="runtime.busy" @change="setArgs(editingTask, $event, 'game_arguments')"></label><label>启动后等待（秒）<input v-model.number="ensureMaaEnd(editingTask).game_wait_seconds" min="0" max="3600" type="number" :disabled="runtime.busy" @change="save"></label><label class="checkbox-label"><input v-model="ensureMaaEnd(editingTask).close_game_on_finish" type="checkbox" :disabled="runtime.busy" @change="save">MaaEnd 结束后关闭本轮启动的游戏</label></div></section>
        <section v-if="editingTask.preset_id" class="editor-section"><div class="section-heading"><div><h3>预设自动规则</h3></div><small>模板提供，只读展示。</small></div><section class="preset-rule-panel"><b>{{ presetLabel(editingTask) }} 模板规则</b><p>{{ presetFor(editingTask)?.note }}</p><dl><dt>日志文件</dt><dd>{{ editingTask.log_path || '无稳定日志终态，使用人工确认。' }}</dd><dt>模板成功规则</dt><dd>{{ presetRuleText(editingTask, 'success') }}</dd><dt>模板失败规则</dt><dd>{{ presetRuleText(editingTask, 'failure') }}</dd><dt>证据</dt><dd>{{ editingTask.preset_evidence || presetFor(editingTask)?.evidence }}</dd></dl></section></section>
        <section class="editor-section"><div class="section-heading"><div><h3>完成信号</h3></div><small>第一个成功信号会锁定当前软件完成。</small></div><fieldset><legend>完成方式</legend><div class="signals"><label><input v-model="editingTask.allow_manual_confirmation" type="checkbox" :disabled="runtime.busy" @change="save">人工确认</label><label><input v-model="editingTask.allow_process_exit" type="checkbox" :disabled="runtime.busy" @change="save">正常退出</label></div><details class="custom-rules"><summary>添加自定义规则</summary><div class="signals"><label>自定义成功<input :value="editingTask.success_log || ''" :disabled="runtime.busy" @change="setText(editingTask, 'success_log', $event)"><select v-model="editingTask.success_log_mode" :disabled="runtime.busy" @change="save"><option value="keyword">关键字</option><option value="regex">正则</option></select></label><label>自定义失败<input :value="editingTask.failure_log || ''" :disabled="runtime.busy" @change="setText(editingTask, 'failure_log', $event)"><select v-model="editingTask.failure_log_mode" :disabled="runtime.busy" @change="save"><option value="keyword">关键字</option><option value="regex">正则</option></select></label></div></details></fieldset></section>
        <section class="editor-section danger-zone"><div class="section-heading"><div><h3>危险操作</h3></div><small>删除后无法恢复当前软件配置。</small></div><button class="danger" :disabled="runtime.busy" @click="deleteScript(editingScript)">删除当前软件脚本</button></section>
      </section></section>
      <section v-else-if="page === 'schedule'" class="plan-page"><div class="plan-page-head"><div><h2>多软件计划</h2><p>计划是唯一的定时单位；到点按软件顺序执行整条计划。</p></div><button class="primary" :disabled="runtime.busy" @click="newPlan">＋ 新建计划</button></div><div class="plan-layout"><aside class="plan-list"><p v-if="!config.plans.length" class="empty">尚无计划。至少有两个软件脚本后可新建。</p><button v-for="plan in config.plans" :key="plan.id" class="plan-list-item" :class="{ active: plan.id === selectedPlanId }" @click="selectedPlanId = plan.id"><b>{{ plan.name }}</b><small>{{ plan.script_ids.length }} 个软件 · 下次：{{ nextTrigger(plan) }}</small><em :class="{ invalid: planIssues(plan).length }">{{ planIssues(plan).length ? '待配置' : '可运行' }}</em></button></aside><section v-if="selectedPlan" class="plan-detail"><div class="plan-detail-head"><label>计划名称<input v-model="selectedPlan.name" :disabled="runtime.busy" @change="save"></label><label class="checkbox-label"><input v-model="selectedPlan.run_on_startup" type="checkbox" :disabled="runtime.busy" @change="setStartupPlan(selectedPlan)">本次后端启动后运行一次</label><button class="danger" :disabled="runtime.busy" @click="deletePlan(selectedPlan)">删除计划</button></div><p v-if="planIssues(selectedPlan).length" class="selection-warning"><b>配置诊断</b><span v-for="issue in planIssues(selectedPlan)" :key="issue">{{ issue }}</span></p><section class="plan-section"><div class="section-heading"><div><h3>软件执行顺序</h3></div><small>拖动或使用上下按钮调整到点后的串行顺序。</small></div><ol class="plan-script-list"><li v-for="(script, index) in planScripts(selectedPlan)" :key="script.id" :draggable="!runtime.busy" @dragstart="draggedPlanScriptId = script.id" @dragover.prevent @drop="dropPlanScript(selectedPlan, script.id)"><b>{{ index + 1 }}</b><span>{{ scriptTask(script)?.name || script.name }}</span><small>{{ presetSummary(script) }}</small><div><button :disabled="runtime.busy || index === 0" @click="movePlanScript(selectedPlan, index, -1)">上移</button><button :disabled="runtime.busy || index === selectedPlan.script_ids.length - 1" @click="movePlanScript(selectedPlan, index, 1)">下移</button><button class="textdanger" :disabled="runtime.busy" @click="removePlanScript(selectedPlan, script.id)">移除</button></div></li></ol><label class="plan-add-script">添加软件<select :disabled="runtime.busy" @change="addPlanScript(selectedPlan, $event)"><option value="">选择软件脚本</option><option v-for="script in config.queues.filter((item) => !selectedPlan!.script_ids.includes(item.id))" :key="script.id" :value="script.id">{{ scriptTask(script)?.name || script.name }}</option></select></label></section><section class="plan-section"><div class="section-heading"><div><h3>定时表</h3></div><button :disabled="runtime.busy" @click="addPlanSlot(selectedPlan)">＋ 添加定时</button></div><div v-if="!selectedPlan.time_slots.length" class="empty-plan">未设置定时；可保留计划供以后手动配置。</div><article v-for="slot in selectedPlan.time_slots" :key="slot.id" class="plan-slot"><label><input v-model="slot.enabled" type="checkbox" :disabled="runtime.busy" @change="save">启用</label><input v-model="slot.time" type="time" :disabled="runtime.busy" @change="save"><div class="days"><label v-for="number in 7" :key="number"><input v-model="slot.days" :value="number - 1" type="checkbox" :disabled="runtime.busy" @change="save">周{{ day(number - 1) }}</label></div><button class="textdanger" :disabled="runtime.busy" @click="removePlanSlot(selectedPlan, slot.id)">删除</button></article></section></section></div></section>
      <section v-else-if="page === 'history'" class="page history-page"><h2>运行历史</h2><p v-if="!history.length">尚无已完成运行。</p><article v-for="run in history" :key="run.id" class="run-record" :class="{ selected: selectedHistoryRunId === run.id, failed: runHasFailures(run) }"><div class="run-record-head"><div><b>{{ run.run_mode === 'plan' ? `计划：${run.queue_name}` : run.run_mode === 'all_scripts' ? '全部软件脚本' : run.queue_name }}</b><small>{{ run.trigger_source }} · {{ run.state }}</small></div><button @click="toggleHistory(run.id)">{{ expandedHistory.has(run.id) ? '收起详情' : runHasFailures(run) ? '查看失败详情' : '查看详情' }}</button></div><ul v-if="expandedHistory.has(run.id)"><li v-for="item in run.items" :key="item.task_id" :class="{ 'history-item-failed': item.state === 'failed' }"><b>{{ item.script_name ? item.script_name + ' / ' : '' }}{{ item.task_name }}</b><span>{{ itemOutcome(item) }}</span><small v-if="item.log_summary?.length">日志：{{ item.log_summary.join('；') }}</small></li></ul><p v-if="run.scheduler_skips?.length" class="schedule-skips"><b>计划跳过</b><span v-for="skip in run.scheduler_skips" :key="skip">{{ skip }}</span></p></article><h2>本轮日志摘要</h2><ol class="logs"><li v-for="(line, index) in logs" :key="index">{{ line }}</li></ol></section>
      <section v-else class="page settings-page"><h2>连接与设置</h2><section class="settings-section"><div class="settings-section-heading"><h3>应用信息</h3></div><dl><dt>开发版本</dt><dd>{{ appVersion }}</dd><dt>数据目录</dt><dd>开发模式根目录 data\；便携版 EXE 同级 data\。</dd><dt>隐私边界</dt><dd>只保存本项目软件脚本、计划、历史和日志；不改写目标软件数据。</dd></dl></section><section class="settings-section"><div class="settings-section-heading"><h3>连接诊断</h3></div><dl><dt>API 状态</dt><dd>{{ connection.restOnline.value ? '在线：保存与运行可用' : '离线：等待后端恢复' }}</dd><dt>实时状态</dt><dd>{{ connection.realtimeLabel.value }}</dd></dl><button @click="refreshDiagnostics">刷新主进程诊断</button><details class="connection-diagnostics"><summary>查看主进程诊断详情</summary><code>{{ diagnosticText }}</code></details></section></section>
    </section></main>
</template>
